# The shared traits say "The creature" or "If the creature". Put the name of each monster in its place.
for _m in MON:
    _m.traits = [(n, t.replace("While the creature", "While the " + _m.ref()).replace("If the creature", "If the " + _m.ref()))
                 for n, t in _m.traits]
